579	/// Splits a string on its `=` character, returning the two substrings on
580	/// either side. Returns `None` if there’s no equals or a string is missing.
581	fn split_on_equals(input: &OsStr) -> Option<(&OsStr, &OsStr)> {
582	    if let Some(index) = os_str_to_bytes(input).iter().position(|elem| *elem == b'=') {
583	        let (before, after) = os_str_to_bytes(input).split_at(index);
584	
585	        // The after string contains the = that we need to remove.
586	        if !before.is_empty() && after.len() >= 2 {
587	            return Some((bytes_to_os_str(before), bytes_to_os_str(&after[1..])));
588	        }
589	    }
590	
591	    None
592	}
